// genuary25
// JAN. 17. (credit: Roni Kaufman)
// What happens if pi=4?

let mySize;

// a shader variable
let theShader;

function preload(){
  theShader = createShader(vert, frag);
}

function setup() {
  mySize = max(windowWidth, windowHeight) * 1.0;
  createCanvas(windowWidth, windowHeight, WEBGL);
  noStroke();
}

function draw() {
  shader(theShader);

  theShader.setUniform("u_resolution", [width, height]);
  theShader.setUniform("u_time", millis() / 1000.0); 
  theShader.setUniform("u_frame", frameCount / 1.0);
  theShader.setUniform("u_mouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) / 100.0, map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, height, 0) / 100.0]);

  rect(0, 0, width, height);
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}


// === Tab: frag ===
const frag = `
#ifdef GL_ES
precision mediump float;
#endif

uniform vec2 u_resolution;
uniform float u_time;
uniform int u_frame;
uniform vec2 u_mouse;

#define pi 4.0
#define MAX_STEPS 5
#define MAX_DIST 10.0
#define SURF_DIST 0.1

mat2 Rot(float a) {
  float s = sin(a), c = cos(a);
  return mat2(c, -s, s, c);
}

float sdBox(vec3 p, vec3 s) {
  float a = atan(p.z, p.x);
  float b = atan(p.z, p.y);
  p = 1.0 + .5 * cos(p + p.x * pi + u_time) - s;
  p.xz += .5 + .5 * cos(8.0 * p.y + u_time);
  return length(max(p, 0.0)) + min(max(p.x, max(p.y, p.z)), 0.0);
}

float GetDist(vec3 p) {
  float d = sdBox(p, vec3(1.0));
  d = mix(length(p) - 3.0, d, 0.15);
  return 2.0 * d;
}

float RayMarch(vec3 ro, vec3 rd) {
  float dO = 0.0;

  for (int i = 0; i < MAX_STEPS; i++) {
    vec3 p = ro + rd * dO;
    float dS = GetDist(p);
    dO += dS;
    if (dO > MAX_DIST || abs(dS) < SURF_DIST) break;
  }

  return dO;
}

vec3 GetNormal(vec3 p) {
  float d = GetDist(p);
  vec2 e = vec2(.01, 0.0);

  vec3 n = d - vec3(
    GetDist(p - e.xyy),
    GetDist(p - e.yxy),
    GetDist(p - e.yyx)
  );

  return normalize(n);
}

vec3 GetRayDir(vec2 uv, vec3 p, vec3 l, float z) {
  vec3 f = normalize(l - p);
  vec3 r = normalize(cross(vec3(0.0, 1.0, 0.0), f));
  vec3 u = cross(f, r);
  vec3 c = f * z;
  vec3 i = c + uv.x * r + uv.y * u;
  return normalize(i);
}

vec3 Bg(vec3 rd) {
  float k = rd.y * 0.5 + 0.5;
  vec3 col = mix(vec3(0.5, 0.0, 0.0), vec3(0.0), k);
  return col;
}

void main() {
  vec2 uv = (gl_FragCoord.xy - 0.5 * u_resolution.xy) / u_resolution.y * 2.0;

  vec3 ro = vec3(0.0, 0.0, 5.0);  // Cámara estática y más cercana

  vec3 rd = GetRayDir(uv, ro, vec3(2.5, -2.0, 0.0), 1.0);
  vec3 col = vec3(0.0);

  float d = RayMarch(ro, rd);

  if (d < MAX_DIST) {
    vec3 p = ro + rd * d;
    vec3 n = GetNormal(p);
    vec3 r = reflect(rd, n);
    vec3 rf = refract(rd, n, 0.2);

    // Ajuste de colores con mayor contraste y movimiento
    float dif = dot(n, normalize(vec3(1.0, 2.0, 3.0))) * 0.5 + 0.0;
    col = 0.25 * vec3(dif);

    col.r += 0.5 + 0.4 * cos(10.0 * rf.y + 4.0 * u_time);
    col.g += 0.3 + 0.3 * sin(6.0 * rf.y + 3.0 * u_time);
    col.b += 0.5 + 0.3 * cos(8.0 * rf.y + 5.0 * u_time);
  }

  col = pow(col, vec3(0.4545));
  gl_FragColor = vec4(col, 1.0);
}
`;



// === Tab: vert ===
const vert = `
attribute vec3 aPosition;
attribute vec2 aTexCoord;

void main() {
  vec4 positionVec4 = vec4(aPosition, 1.0);
  positionVec4.xy = positionVec4.xy * 2.0 - 1.0;
  gl_Position = positionVec4;
}
`;

